fn classify(n:i32)->num{if n<0{return 0;}else if n==0{return 1;}else if n<10{return 2;}else{return 3;}}
fn main(){assert(classify(-5)==0);assert(classify(0)==1);assert(classify(7)==2);assert(classify(70)==3);
 b:=bytes[1];mut x=0;if false{x=1;}else if true{x=2;}assert(x==2);println(42);}

struct Point{x:i32,y:i32}
impl Point{fn sum<a>(self:ref<a,Point>)->i32{return self.x+self.y;}fn shift<a>(self:ref_mut<a,Point>,dx:i32){self.x=self.x+dx;}}
struct Shape{origin:Point,size:num}
impl Shape{fn moved<a>(self:ref_mut<a,Shape>){self.origin.shift(5);}fn total<a>(self:ref<a,Shape>)->i32{return self.origin.sum();}}
fn main(){mut s=Shape{origin:Point{x:1,y:2},size:3};assert(s.origin.sum()==3);s.origin.shift(1);assert(s.origin.sum()==4);s.moved();assert(s.total()==9);println(42);}

struct Point{x:i32,y:i32}
impl Point{fn new(x:i32,y:i32)->Point{return Point{x:x,y:y};}fn sum<a>(self:ref<a,Point>)->i32{return self.x+self.y;}fn grow<a>(self:ref_mut<a,Point>)->i32{self.x=self.x+1;return self.x;}}
struct Bag{items:vec<bytes>}
impl Bag{fn make()->Bag{return Bag{items:vec<bytes>[bytes[1],bytes[2]]};}fn count<a>(self:ref<a,Bag>)->num{return self.items.len();}}
fn main(){assert(Point::new(1,2).sum()==3);assert(Point::new(5,0).grow()==6);assert(Bag::make().count()==2);println(42);}

use core;
fn first(v:vec<num>)->core::Option<num>{if v.len()==0{return core::none<num>();}return core::some(v[0]);}
fn label(o:core::Option<bytes>)->num{if let Some(b) = o {return b.len();} else {return 0;}}
fn main(){
    if let Some(x) = first(vec<num>[7,8]) {assert(x==7);} else {assert(false);}
    if let Some(x) = first(vec<num>[]) {assert(false);}
    assert(label(core::some(bytes[1,2,3]))==3);assert(label(core::none<bytes>())==0);
    r:=core::err<num,bytes>(bytes[5]);if let Ok(v) = r {assert(false);} else if true {println(42);}
}

use core;
fn pop<a>(v:ref_mut<a,vec<bytes>>)->core::Option<bytes>{if v.len()==0{return core::none<bytes>();}return core::some(v.pop());}
fn main(){
    mut stack=vec<bytes>[bytes[1],bytes[2,2],bytes[3,3,3]];mut total=0;
    while let Some(item) = pop(borrow_mut(stack)) {total+=item.len();}
    assert(total==6);
    mut n=0;mut more=vec<bytes>[bytes[1],bytes[2]];
    while let Some(x) = pop(borrow_mut(more)) {n+=1;if n==1{break;}}
    assert(n==1);println(42);
}

fn count_slashes<a>(path:read<a>)->num{mut n=0;for b in path{if b=='/'{n+=1;}}return n;}
fn main(){assert('a'==97);assert('\n'==10);assert('\''==39);assert('\\'==92);x:='z'-'a';assert(x==25);u:=1u8;assert(u+'0'==49);
 assert(count_slashes(&"/usr/local/bin")==3);println(42);}

struct Point{x:i32,y:i32}
impl Point{fn show<a>(self:ref<a,Point>)->string{return format("({}, {})", self.x, self.y);}}
struct Line{from:Point,to:Point}
impl Line{fn show<a>(self:ref<a,Line>)->string{return format("{} -> {}", self.from, self.to);}}
fn main(){p:=Point{x:1,y:-2};println(p);println("p = {}", p);l:=Line{from:Point{x:0,y:0},to:Point{x:3,y:4}};s:=format("line {}", l);println(s);println(p.x);}

enum Shape{Circle(num),Square(num),Empty}
impl Shape{
    fn area<a>(self:ref<a,Shape>)->num{match self{Circle(r)=>{return 3*r*r;},Square(s)=>{return s*s;},Empty=>{return 0;}}}
    fn show<a>(self:ref<a,Shape>)->string{return format("shape with area {}", self.area());}
}
fn main(){c:=Shape::Circle(2);assert(c.area()==12);s:=Shape::Square(3);println(s);e:=Shape::Empty;assert(e.area()==0);println(42);}

use core;
enum Message{Text(bytes),Count(num),Quit}
fn describe<a>(m:ref<a,Message>)->num{match m{Text(t)=>{return t.len();},Count(n)=>{return n;},Quit=>{return 0;}}}
fn grow<a>(m:ref_mut<a,Message>){match m{Text(t)=>{t.push(9);},Count(n)=>{},Quit=>{}}}
fn main(){mut m=Message::Text(bytes[1,2]);assert(describe(borrow(m))==2);grow(borrow_mut(m));assert(describe(borrow(m))==3);
 assert(describe(borrow(m))==3);c:=Message::Count(7);assert(describe(borrow(c))==7);
 o:=core::some(bytes[5]);match borrow(o){Some(b)=>{assert(b[0]==5);},None=>{}}assert(o!.len()==1);println(42);}

