 mut acc=Acc{total:0.0,count:0};acc.total+=2.5;acc.count+=1;acc.count+=1;println("{} {}", acc.total, acc.count);mut n=5;n+=1;println(n);}

fn name(n:num)->string{match n{0=>{return "zero".text();},1|2=>{return "small".text();},_=>{return format("{}", n);}}}
fn sign(x:i32)->i32{match x{0=>{return 0;},-1=>{return -1;},_=>{if x<0{return -1;}return 1;}}}
fn kind(b:u8)->num{match b{'a'|'e'|'i'|'o'|'u'=>{return 1;},' '=>{return 2;},_=>{return 0;}}}
fn yes(f:bool)->num{match f{true=>{return 1;},false=>{return 0;}}}
fn main(){println(name(0));println(name(2));println(name(42));println(sign(-1));println(sign(-7));println(sign(9));
 mut vowels=0;for b in "education is fun"{if kind(u8(b))==1{vowels+=1;}}println(vowels);println(yes(3>2));
 owned:=bytes[1];mut n=0;match owned.len(){1=>{n=10;},_=>{n=20;}}println(n);}

fn grade(score:num)->u8{match score{90..101=>{return 'A';},80..90=>{return 'B';},0..80=>{return 'C';},_=>{return '?';}}}
fn band(t:i32)->num{match t{-40..0=>{return 0;},0..25=>{return 1;},25..50=>{return 2;},_=>{return 9;}}}
fn main(){println(grade(95));println(grade(85));println(grade(12));println(grade(200));println(band(-10));println(band(0));println(band(30));println(band(-41));println(band(50));}

