enum M{Text(bytes),Num(num),Quit}
fn kind(m:M)->num{match m{Num(n)=>{return n;},_=>{return 0;}}}
fn peek<a>(m:ref<a,M>)->num{match m{Text(t)=>{return t.len();},_=>{return 99;}}}
fn main(){assert(kind(M::Text(bytes[1,2,3]))==0);assert(kind(M::Num(5))==5);assert(kind(M::Quit)==0);t:=M::Text(bytes[9]);assert(peek(borrow(t))==1);q:=M::Quit;assert(peek(borrow(q))==99);println(42);}

fn describe(n:i32)->string{match n{0=>{return "zero".text();},x if x<0=>{return format("negative {}", x);},x if x%2==0=>{return format("even {}", x);},other=>{return format("odd {}", other);}}}
fn main(){println(describe(0));println(describe(-3));println(describe(8));println(describe(7));
 limit:=5;mut hits=0;for i in 10{match i{1|2 if limit>3=>{hits+=10;},n if n>=limit=>{hits+=1;},_=>{}}}println(hits);}

use order;
use hash;
struct Version{major:num,minor:num}
impl order::Ord for Version{fn less<a,b>(left:ref<a,Self>,right:ref<b,Self>)->bool{if left.major!=right.major{return left.major<right.major;}return left.minor<right.minor;}}
interface Area{fn area<a>(shape:ref<a,Self>)->num;}
struct Square{side:num}
impl Area for Square{fn area<a>(shape:ref<a,Self>)->num{return shape.side*shape.side;}}
fn main(){a:=Version{major:1,minor:4};b:=Version{major:1,minor:10};println(a.less(borrow(b)));println(b.less(borrow(a)));s:=Square{side:7};println(s.area());r:=borrow(s);println(r.area());}

fn divide(a:num,b:num)->(num,num){return (a/b,a%b);}
fn min_max(v:vec<i32>)->(i32,i32){mut lo=v[0];mut hi=v[0];for x in v{if x<lo{lo=x;}if x>hi{hi=x;}}return (lo,hi);}
fn split<a>(text:read<a>)->(bytes,bytes){mut l=bytes[];mut r=bytes[];mut seen=false;for b in text{if b=='='{seen=true;}else{if seen{r.push(b);}else{l.push(b);}}}return (l,r);}
fn first<a>(pair:ref<a,(num,bytes)>)->num{return pair.0;}
fn main(){
    (q,r):=divide(17,5);println("{} {}", q, r);
    t:=min_max(vec<i32>[3,-2,9]);println("{} {}", t.0, t.1);
    (key,value):=split(&"name=grail");println("{} -> {}", key, value);
    p:=(7,bytes[1,2]);println(first(borrow(p)));println(p.1.len());
    mut m=(1,2.5,true);m.0=5;println("{} {} {}", m.0, m.1, m.2);
    (_,kept):=(bytes[9],bytes[8,8]);println(kept.len());
    nested:=((1,2),3);inner:=nested.0;println(inner.1+nested.1);
}

struct Person{name:string,age:u32}
fn total<a>(people:ref<a,vec<Person>>)->u32{mut sum: u32 = 0;for p in people{sum+=p.age;}return sum;}
fn birthday<a>(people:ref_mut<a,vec<Person>>){for p in people{p.age+=1;}}
fn main(){mut people=vec<Person>[Person{name:"Ann".text(),age:30},Person{name:"Bo".text(),age:25}];
 for p in borrow(people){println("{} {}", p.name, p.age);}println(total(borrow(people)));birthday(borrow_mut(people));println(total(borrow(people)));
 words:=vec<bytes>[bytes[1,2],bytes[3]];mut n=0;for w in borrow(words){n+=w.len();if n>100{break;}}println(n);people.push(Person{name:"Cy".text(),age:1});println(people.len());}

use vecs;
fn scale_all<T>(items:vec<T>,factor:num,f:Fn(T,num)->T)->vec<T>{offset:=factor;return vecs::map(items,|x: T| -> T f(x,offset));}
fn times(x:num,k:num)->num{return x*k;}
fn twice<T>(v:T,g:Fn(T)->T)->T{h:=|y: T| -> T g(y);return h(v);}
fn main(){r:=scale_all(vec<num>[1,2,3],10,|x: num, k: num| -> num x*k);println(r);println(twice(5,|x: num| -> num x+1));s:=twice(bytes[1],|b: bytes| -> bytes b);println(s.len());}

